<script>
const starter = `# Welcome to StackEdit!

Hi! I'm your first Markdown file in **StackEdit**. If you want to learn to use StackEdit, you can read me. If you want to play with Markdown, you can edit me. Once you have finished with me, you can create new files by opening the **file explorer** on the left corner of the navigation bar.

## Files

StackEdit stores your files in your browser, which means all your files are automatically saved locally and are accessible **offline!**

## Create files and folders

The file explorer is accessible using the button in left corner of the navigation bar. You can create a new file by clicking the **New file** button in the file explorer. You can also create folders by clicking the **New folder** button.

## Switch to another file

All your files and folders are presented as a tree in the file explorer. You can switch from one to another by clicking a file in the tree.

## Rename a file

You can rename the current file by clicking the file name in the navigation bar or by clicking the **Rename** button in the file explorer.

## Delete a file

You can delete the current file by clicking the **Remove** button in the file explorer. The file will be moved into the **Trash** folder and automatically deleted after 7 days of inactivity.

## Export a file

You can export the current file by clicking **Export to disk** in the menu. You can choose to export the file as plain Markdown, as HTML using a Handlebars template or as a PDF.`;

const editor = document.getElementById('editor');
const preview = document.getElementById('preview');
const leftStatus = document.getElementById('leftStatus');
const rightStatus = document.getElementById('rightStatus');
const toast = document.getElementById('toast');
editor.value = starter;

function inlineMd(s) {
  return s
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img alt="$1" src="$2">')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/~~(.+?)~~/g, '<del>$1</del>');
}
function renderMarkdown(src) {
  const lines = src.split('\n'), out = [];
  let list = '';
  const endList = () => { if (list) { out.push(`</${list}>`); list = ''; } };
  for (const line of lines) {
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    const li = line.match(/^\s*(?:[-*+]|\d+\.)\s+(.*)$/);
    if (li) {
      const typ = /^\s*\d+\./.test(line) ? 'ol' : 'ul';
      if (list !== typ) { endList(); list = typ; out.push(`<${typ}>`); }
      out.push(`<li>${inlineMd(li[1])}</li>`); continue;
    }
    endList();
    if (!line.trim()) continue;
    if (/^\s*([-*_])\s*\1\s*\1\s*$/.test(line)) { out.push('<hr>'); continue; }
    if (h) { const n = h[1].length; out.push(`<h${n}>${inlineMd(h[2])}</h${n}>`); continue; }
    if (/^>\s?/.test(line)) { out.push(`<blockquote><p>${inlineMd(line.replace(/^>\s?/, ''))}</p></blockquote>`); continue; }
    out.push(`<p>${inlineMd(line)}</p>`);
  }
  endList();
  return out.join('');
}
function update() {
  preview.innerHTML = renderMarkdown(editor.value);
  const value = editor.value;
  const pos = editor.selectionStart;
  const before = value.slice(0, pos).split('\n');
  const line = before.length, col = before[before.length - 1].length + 1;
  const words = (value.match(/\b[\w'-]+\b/g) || []).length;
  const bytes = new TextEncoder().encode(value).length;
  leftStatus.innerHTML = `Markdown &nbsp; ${bytes} bytes &nbsp; ${words} words &nbsp; ${value.split('\n').length} lines &nbsp; Ln ${line}, Col ${col}`;
  const plain = preview.innerText || '';
  rightStatus.innerHTML = `HTML &nbsp; ${plain.length} characters &nbsp; ${(plain.match(/\b[\w'-]+\b/g)||[]).length} words &nbsp; ${preview.children.length} paragraphs`;
}
editor.addEventListener('input', update);
editor.addEventListener('click', update);
editor.addEventListener('keyup', update);
update();

function wrapSelection(before, after = before, placeholder = '') {
  const start = editor.selectionStart, end = editor.selectionEnd;
  const text = editor.value.slice(start, end);
  const selected = text || placeholder;
  editor.setRangeText(before + selected + after, start, end, 'select');
  if (!text) editor.setSelectionRange(start + before.length, start + before.length + selected.length);
  editor.focus(); update();
}
function prefixLines(prefix) {
  const start = editor.selectionStart, end = editor.selectionEnd;
  const value = editor.value;
  const lineStart = value.lastIndexOf('\n', start - 1) + 1;
  let lineEnd = value.indexOf('\n', end);
  if (lineEnd < 0) lineEnd = value.length;
  const block = value.slice(lineStart, lineEnd);
  const lines = block.split('\n');
  const transformed = lines.map(l => prefix + l).join('\n');
  editor.setRangeText(transformed, lineStart, lineEnd, 'select');
  editor.focus(); update();
}
function headingSelection() {
  const start = editor.selectionStart, value = editor.value;
  const lineStart = value.lastIndexOf('\n', start - 1) + 1;
  let end = value.indexOf('\n', start); if (end < 0) end = value.length;
  const line = value.slice(lineStart, end);
  const changed = line.match(/^#{1,6}\s/) ? line.replace(/^#{1,6}\s/, '') : '### ' + line;
  editor.setRangeText(changed, lineStart, end, 'select');
  editor.focus(); update();
}
document.querySelectorAll('[data-action]').forEach(btn => {
  btn.addEventListener('mousedown', e => e.preventDefault());
  btn.addEventListener('click', () => {
    const action = btn.dataset.action;
    if (action === 'bold') wrapSelection('**', '**', 'bold text');
    else if (action === 'italic') wrapSelection('*', '*', 'italic text');
    else if (action === 'strike') wrapSelection('~~', '~~', 'strikethrough');
    else if (action === 'code') wrapSelection('`', '`', 'code');
    else if (action === 'link') wrapSelection('[', '](url)', 'link text');
    else if (action === 'image') wrapSelection('![', '](image-url)', 'alt text');
    else if (action === 'quote') prefixLines('> ');
    else if (action === 'ul') prefixLines('- ');
    else if (action === 'ol') prefixLines('1. ');
    else if (action === 'check') prefixLines('- [ ] ');
    else if (action === 'heading') headingSelection();
    else if (action === 'table') wrapSelection('| Column 1 | Column 2 |\\n| --- | --- |\\n| Cell | Cell |', '', '');
    else if (action === 'undo') document.execCommand('undo');
    else if (action === 'redo') document.execCommand('redo');
  });
});
document.getElementById('explorerBtn').addEventListener('click', () => {
  document.getElementById('fileMenu').classList.toggle('open');
});
document.getElementById('renameBtn').addEventListener('click', () => {
  const name = prompt('Rename file', 'Welcome file');
  if (name) document.getElementById('renameBtn').textContent = name;
});
document.querySelectorAll('.file-menu .item').forEach(item => item.addEventListener('click', () => {
  if (item.textContent.includes('New file')) {
    editor.value = '# New file\\n\\n'; update(); editor.focus();
  }
}));
document.querySelector('.badge').addEventListener('click', () => {
  toast.style.display = 'block'; setTimeout(() => toast.style.display = 'none', 2400);
});
let dragging = false;
const splitter = document.getElementById('splitter');
splitter.addEventListener('mousedown', () => dragging = true);
window.addEventListener('mouseup', () => dragging = false);
window.addEventListener('mousemove', e => {
  if (!dragging) return;
  const workspace = document.getElementById('workspace');
  const r = workspace.getBoundingClientRect();
  const x = Math.max(250, Math.min(r.width - 250, e.clientX - r.left));
  workspace.style.gridTemplateColumns = `${x}px 8px 1fr`;
});
</script>
</body>
</html>
